// ---- helpers (shared by the workflows in this pack) ----
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const today = now.startOf('day');

// Read the first non-empty value among several possible column names.
const val = (row, ...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// Accepts 2026-11-20, 2026-11-20T14:30, 11/20/2026, 20.11.2026, Nov 20, 2026 or a Sheets serial number.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' })
      .setZone(zone, { keepLocalTime: true });
  }
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone });
  if (d.isValid) return d;
  d = DateTime.fromSQL(s, { zone });
  if (d.isValid) return d;
  for (const f of ['M/d/yyyy', 'M/d/yyyy H:mm', 'M/d/yyyy h:mm a', 'M/d/yy', 'd.M.yyyy', 'yyyy/M/d', 'd MMM yyyy', 'MMM d, yyyy', 'MMMM d, yyyy']) {
    d = DateTime.fromFormat(s, f, { zone });
    if (d.isValid) return d;
  }
  const js = new Date(s);
  return isNaN(js) ? null : DateTime.fromJSDate(js).setZone(zone);
}

// Whole days between a date and today (positive = in the past).
const daysAgo = (d) => Math.round(today.diff(d.startOf('day'), 'days').days);

const firstName = (name) => (String(name || '').trim().split(/\s+/)[0] || 'there');

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

function money(amount, currency) {
  const cur = (currency || cfg.currency || 'USD').toUpperCase();
  try {
    return new Intl.NumberFormat(cfg.locale || 'en-US', { style: 'currency', currency: cur }).format(toNumber(amount));
  } catch (e) {
    return cur + ' ' + toNumber(amount).toFixed(2);
  }
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const button = (url, label) => url
  ? `<p style="margin:24px 0"><a href="${esc(url)}" style="background:${cfg.brandColor || '#2563eb'};color:#ffffff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">${esc(label)}</a></p>`
  : '';

// Wraps body HTML in a clean, mobile-friendly email layout.
const layout = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">${inner}<p style="margin-top:32px;color:#6b7280;font-size:13px">${esc(cfg.businessName || '')}</p></div>`;
// ---- end helpers ----

// Reminder schedule. offset = days relative to the due date (negative = before it's due).
// EDIT the wording here if you like — {name}, {id}, {amount}, {due}, {days} get filled in for you.
const STAGES = [
  { key: 'before-3',  offset: -3, subject: 'Friendly reminder: invoice {id} is due {due}',
    body: 'Just a friendly heads-up that invoice <b>{id}</b> for <b>{amount}</b> is due on <b>{due}</b>. If you\'ve already arranged payment, thank you — please ignore this email.' },
  { key: 'due',       offset: 0,  subject: 'Invoice {id} is due today',
    body: 'Invoice <b>{id}</b> for <b>{amount}</b> is due today. You can pay in a minute using the button below.' },
  { key: 'overdue-7', offset: 7,  subject: 'Invoice {id} is now {days} days overdue',
    body: 'Our records show invoice <b>{id}</b> for <b>{amount}</b> (due {due}) is now <b>{days} days overdue</b>. Could you take a moment to settle it, or let us know if there\'s a problem?' },
  { key: 'overdue-14', offset: 14, subject: 'Second notice: invoice {id} is {days} days overdue',
    body: 'This is a second reminder that invoice <b>{id}</b> for <b>{amount}</b> is <b>{days} days overdue</b>. Please arrange payment this week. If something is wrong with the invoice, just reply and we\'ll sort it out.' },
  { key: 'final-30',  offset: 30, subject: 'Final notice: invoice {id} ({amount}) is {days} days overdue',
    body: 'Invoice <b>{id}</b> for <b>{amount}</b> is now <b>{days} days overdue</b>. Please pay within 7 days or contact us to agree a payment plan, otherwise we may need to pause work on your account.' },
];
const ORDER = STAGES.map((s) => s.key);
const DONE = ['paid', 'void', 'cancelled', 'canceled', 'written off'];

const out = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  const id = val(r, 'Invoice ID');
  const email = val(r, 'Client Email');
  if (!id || !email || DONE.includes(val(r, 'Status').toLowerCase())) return;
  const due = parseDate(r['Due Date']);
  if (!due) return;

  const days = daysAgo(due); // positive = overdue
  let stage = null;
  for (const s of STAGES) if (days >= s.offset) stage = s;
  if (!stage) return;                                                          // too early
  if (ORDER.indexOf(stage.key) <= ORDER.indexOf(val(r, 'Last Reminder Stage'))) return; // already sent

  const fill = (t) => t
    .replace(/{name}/g, esc(firstName(val(r, 'Client Name'))))
    .replace(/{id}/g, esc(id))
    .replace(/{amount}/g, money(r['Amount'], val(r, 'Currency')))
    .replace(/{due}/g, due.toFormat('d LLL yyyy'))
    .replace(/{days}/g, String(Math.abs(days)));

  out.push({
    json: {
      invoiceId: id,
      clientEmail: email,
      stage: stage.key,
      subject: fill(stage.subject).replace(/<[^>]+>/g, ''),
      html: layout(`<p>Hi ${esc(firstName(val(r, 'Client Name')))},</p><p>${fill(stage.body)}</p>`
        + button(val(r, 'Payment Link'), 'Pay invoice ' + id)
        + '<p>Thank you!</p>'),
      sentOn: today.toISODate(),
    },
    pairedItem: { item: i },
  });
});
return out;
